def compact_base64(data: bytes) -> str:
    return base64.b64encode(gzip.compress(data, compresslevel=9, mtime=0)).decode("ascii")


def pack_forest(model) -> dict:
    """Serializa el preprocesador y los árboles del Pipeline de demand_agent."""
    preprocessor = model.named_steps["preprocess"]
    numeric_columns = []
    categorical_columns = []
    for name, _, columns in preprocessor.transformers_:
        if name == "numeric":
            numeric_columns = list(columns)
        elif name == "categorical":
            categorical_columns = list(columns)

    numeric = preprocessor.named_transformers_["numeric"]
    categorical = preprocessor.named_transformers_["categorical"]
    scaler = numeric.named_steps["scale"]
    categories = categorical.named_steps["onehot"].categories_

    trees = []
    for estimator in model.named_steps["model"].estimators_:
        tree = estimator.tree_
        packed = bytearray()
        for node in range(tree.node_count):
            packed.extend(struct.pack(
                "<iiidd",
                int(tree.children_left[node]),
                int(tree.children_right[node]),
                int(tree.feature[node]),
                float(tree.threshold[node]),
                float(tree.value[node, 0, 0]),
            ))
        trees.append(base64.b64encode(gzip.compress(bytes(packed), 9, mtime=0)).decode("ascii"))

    return {
        "selected_features": list(model.named_steps["select"].columns),
        "numeric": {
            "columns": numeric_columns,
            "medians": numeric.named_steps["impute"].statistics_.tolist(),
            "means": scaler.mean_.tolist(),
            "scales": scaler.scale_.tolist(),
        },
        "categorical": {
            "columns": categorical_columns,
            "medians": categorical.named_steps["impute"].statistics_.tolist(),
            "categories": [category.tolist() for category in categories],
        },
        "trees": trees,
    }


